-- Daily challenges for 2026-10-18: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-18. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('keeping-a-simple-journal', 'Keeping a Simple Journal', 'For anyone who would like to write things down but never knows where to start. Each day is one short prompt or page habit, a few lines in a notebook or on your phone, to sort your thoughts, remember good moments and know yourself a little better.', 'Mindfulness', 365, array['Self-Care', 'Emotion Regulation', 'Habits']::text[], 1, '2026-10-18T17:00:00+00:00'::timestamptz),
  ('starting-conversations-with-strangers', 'Starting Conversations with Strangers', 'For anyone who would like a little more friendly contact in daily life. Each day is one small, low-stakes way to say hello, ask a question or share a kind word with someone you don''t know, from a cashier to a neighbor at the bus stop.', 'Connection', 365, array['Loneliness', 'Social Anxiety', 'Communication']::text[], 1, '2026-10-18T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('keeping-a-simple-journal', 'starting-conversations-with-strangers');

